    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int best = -1;

    for (long long i = 1; i <= 45500; ++i) {
        string square = to_string(i * i);
        size_t pos = 0;

        for (char digit : s) {
            if (pos < square.size() && digit == square[pos]) {
                ++pos;
            }
        }

        if (pos == square.size()) {
            best = max(best, static_cast<int>(square.size()));
        }
    }

    cout << (best == -1 ? -1 : static_cast<int>(s.size()) - best) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    vector<vector<ll>> squares(11);

    for (ll i = 1; i <= 45500; ++i) {
        ll square = i * i;
        squares[to_string(square).size()].push_back(square);
    }

    size_t maxLength = min<size_t>(s.size(), squares.size() - 1);

    for (size_t length = maxLength; length >= 1; --length) {
        for (ll square : squares[length]) {
            string candidate = to_string(square);
            size_t position = 0;

            for (char digit : s) {
                if (position < candidate.size() && digit == candidate[position]) {
                    ++position;
                }
            }

            if (position == candidate.size()) {
                cout << s.size() - candidate.size() << '\n';
                return 0;
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

