#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    vector<vector<long long>> squares(max<size_t>(11, s.size() + 1));

    for (long long i = 1; i <= 45500; ++i) {
        long long square = i * i;
        string value = to_string(square);
        squares[value.size()].push_back(square);
    }

    for (int length = static_cast<int>(s.size()); length >= 1; --length) {
        if (length >= static_cast<int>(squares.size())) {
            continue;
        }

        for (long long square : squares[length]) {
            string candidate = to_string(square);
            size_t position = 0;

            for (char digit : s) {
                if (position < candidate.size() && digit == candidate[position]) {
                    ++position;
                }
            }

            if (position == candidate.size()) {
                cout << s.size() - candidate.size() << '\n';
                return 0;
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

